function load():State{try{const raw=localStorage.getItem('nexo-office-v1');if(raw){const value=JSON.parse(raw);if(Array.isArray(value.agents)&&Array.isArray(value.tasks)&&value.messages&&value.preferences)return {...value,agents:arrangeAgents(withManager(value.agents)),collaborations:recoverCollaborations(Array.isArray(value.collaborations)?value.collaborations.filter(c=>c&&Array.isArray(c.stages)):[])};}}catch{}return emptyState();}
