 const [panel,setPanel]=useState<string|null>(null),[selected,setSelected]=useState<string|null>(null),[expanded,setExpanded]=useState(()=>{try{return localStorage.getItem('nexo-sidebar-pinned')==='true';}catch{return false;}}),[configured,setConfigured]=useState(false),[apiReady,setApiReady]=useState(false),[apiError,setApiError]=useState(''),[toast,setToast]=useState(''),[search,setSearch]=useState(''),[taskView,setTaskView]=useState<'kanban'|'list'>('kanban'),[editingAgent,setEditingAgent]=useState<Agent|null>(null),[newAgent,setNewAgent]=useState(false),[filterAgent,setFilterAgent]=useState(''),[focusedTask,setFocusedTask]=useState<string|null>(null),[draft,setDraft]=useState(''),[attachments,setAttachments]=useState<Attachment[]>([]),[busy,setBusy]=useState<Record<string,boolean>>({}),[taskIntent,setTaskIntent]=useState(false),[editingProposal,setEditingProposal]=useState<Message|null>(null),[sceneError,setSceneError]=useState('');
 const scene=useRef<ReturnType<typeof createOffice>|null>(null),stage=useRef<HTMLDivElement>(null),end=useRef<HTMLDivElement>(null),drafts=useRef<Record<string,string>>({});
 const busyRef=useRef(busy);busyRef.current=busy;
 const interaction=useRef({panel,selected});interaction.current={panel,selected};
 const agent=state.agents.find(a=>a.id===selected);const currentTask=state.tasks.find(t=>t.id===focusedTask);const mainOpen=panel!==null;const working=state.agents.filter(a=>agentStatus(state,a.id)==='working').length;const resumeCount=resumableManagerProjects(state).length;const featuredPlan=featuredManagerProject(state);const previousManagerMessages=state.messages[MANAGER_ID]||[];const featuredManagerMessageId=[...previousManagerMessages].reverse().find(message=>message.teamPlan?.id===featuredPlan?.id)?.id;
