 useEffect(()=>{let disposed=false;import('./office').then(({createOffice})=>{if(disposed||!stage.current)return;const current=stateRef.current;scene.current=createOffice(stage.current,current.agents,toggleAgent,id=>agentStatus(stateRef.current,id));scene.current.setMeetings(meetingAssignments(current.collaborations),current.collaborations.filter(occupiesRoom).map(c=>c.roomId));scene.current.setLight(current.preferences.dark);const {panel,selected}=interaction.current;scene.current.setConversation(panel==='chat'?selected:null);if((panel==='chat'||panel==='agent')&&selected)scene.current.focus(selected);setSceneReady(true);}).catch(()=>{if(!disposed)setSceneError('Não foi possível iniciar o 3D. Você ainda pode acessar os agentes pelo menu.');});return ()=>{disposed=true;scene.current?.dispose();};},[]);
